extension Ws.Fs.Upload.Start {
    /// In a share session: the share upload surface (target resolved inside the share).
    public enum ShareMode: WsRequest {
        public static let command = WsCommand.fsUploadStart

        public struct Payload: Codable, Hashable, Sendable {
            /// Vault id. Minimum 0. nil omits it, `.null` sends null.
            public var vaultID: Nullable<Int64>?
            /// Share-relative path (the share root when absent).
            public var path: String?
            public var filename: String?
            /// Minimum 0.
            public var sizeBytes: Int64?
            /// Minimum 0.
            public var size: Int64?
            /// nil omits it, `.null` sends null.
            public var mimeType: Nullable<String>?
            public var duplicatePolicy: DuplicatePolicy?

            public init(vaultID: Nullable<Int64>? = nil, path: String? = nil, filename: String? = nil,
                        sizeBytes: Int64? = nil, size: Int64? = nil, mimeType: Nullable<String>? = nil,
                        duplicatePolicy: DuplicatePolicy? = nil) {
                self.vaultID = vaultID
                self.path = path
                self.filename = filename
                self.sizeBytes = sizeBytes
                self.size = size
                self.mimeType = mimeType
                self.duplicatePolicy = duplicatePolicy
            }

            enum CodingKeys: String, CodingKey {
                case vaultID = "vault_id"
                case path
                case filename
                case sizeBytes = "size_bytes"
                case size
                case mimeType = "mime_type"
                case duplicatePolicy = "duplicate_policy"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.vaultID = container.contains(.vaultID)
                    ? try container.decode(Nullable<Int64>.self, forKey: .vaultID) : nil
                self.path = try container.decodeIfPresent(String.self, forKey: .path)
                self.filename = try container.decodeIfPresent(String.self, forKey: .filename)
                self.sizeBytes = try container.decodeIfPresent(Int64.self, forKey: .sizeBytes)
                self.size = try container.decodeIfPresent(Int64.self, forKey: .size)
                self.mimeType = container.contains(.mimeType)
                    ? try container.decode(Nullable<String>.self, forKey: .mimeType) : nil
                self.duplicatePolicy = try container.decodeIfPresent(DuplicatePolicy.self, forKey: .duplicatePolicy)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encodeIfPresent(self.vaultID, forKey: .vaultID)
                try container.encodeIfPresent(self.path, forKey: .path)
                try container.encodeIfPresent(self.filename, forKey: .filename)
                try container.encodeIfPresent(self.sizeBytes, forKey: .sizeBytes)
                try container.encodeIfPresent(self.size, forKey: .size)
                try container.encodeIfPresent(self.mimeType, forKey: .mimeType)
                try container.encodeIfPresent(self.duplicatePolicy, forKey: .duplicatePolicy)
            }

            public enum DuplicatePolicy: String, Codable, Hashable, Sendable, CaseIterable {
                case reject
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var uploadID: String
            public var transferID: String
            public var path: String
            public var filename: String
            /// Minimum 0.
            public var sizeBytes: Int64
            /// Minimum 0.
            public var chunkSize: Int64
            public var duplicatePolicy: String

            public init(uploadID: String, transferID: String, path: String, filename: String, sizeBytes: Int64,
                        chunkSize: Int64, duplicatePolicy: String) {
                self.uploadID = uploadID
                self.transferID = transferID
                self.path = path
                self.filename = filename
                self.sizeBytes = sizeBytes
                self.chunkSize = chunkSize
                self.duplicatePolicy = duplicatePolicy
            }

            enum CodingKeys: String, CodingKey {
                case uploadID = "upload_id"
                case transferID = "transfer_id"
                case path
                case filename
                case sizeBytes = "size_bytes"
                case chunkSize = "chunk_size"
                case duplicatePolicy = "duplicate_policy"
            }
        }
    }
}
